def coloring(i, j):
    # Using 1-based indexing for the grid coordinates (i, j)
    # Color is based on (i + j) mod 4 + 1
    return ((i + j - 2) % 4) + 1 # Adjusting for 1-based index i, j vs 0-based math

N = 4
grid = []
for i in range(1, N + 1):
    row = [coloring(i, j) for j in range(1, N + 1)]
    grid.append(row)

print(f"--- {N}x{N} grid coloring ---")
for row in grid:
    print(row)

# Check all 2x2 subgrids (N-1) x (N-1)
for i in range(1, N):
    for j in range(1, N):
        block = [
            grid[i-1][j-1],
            grid[i][j-1],
            grid[i-1][j],
            grid[i][j]
        ]
        counts = {}
        for color in block:
            counts[color] = counts.get(color, 0) + 1

        # Constraint check: At least one color must appear twice or more
        if not any(count >= 2 for count in counts.values()):
            print(f"Failure found at ({i}, {j}): {block}")
            break
    else:
        continue
    break
else:
    print("All 2x2 subgrids satisfy the constraint.")

